// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_target != address(0));
        vm.assume(_target != address(c));
        vm.assume(_value <= 1 ether);
        vm.assume(_data.length <= 256);

        vm.deal(address(this), 10 ether);
        vm.prank(c.owner());

        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.sendMoney.selector, _target, _value, _data)
        );

        assertTrue(success);
    }
}

